python3 -c "
from html.parser import HTMLParser

class HTMLValidator(HTMLParser):
    def __init__(self):
        super().__init__()
        self.tags = []
        self.errors = []

    def handle_starttag(self, tag, attrs):
        if tag not in ['br', 'hr', 'img', 'input', 'meta', 'link', 'area', 'base', 'col', 'embed', 'param', 'source', 'track', 'wbr']:
            self.tags.append(tag)

    def handle_endtag(self, tag):
        if tag not in ['br', 'hr', 'img', 'input', 'meta', 'link', 'area', 'base', 'col', 'embed', 'param', 'source', 'track', 'wbr']:
            if self.tags and self.tags[-1] == tag:
                self.tags.pop()
            else:
                self.errors.append(f'Unexpected closing tag: {tag}')

with open('/app/output/index.html', 'r') as f:
    content = f.read()

validator = HTMLValidator()
validator.feed(content)

if validator.errors:
    print('HTML Errors:')
    for e in validator.errors:
        print(f'  {e}')
else:
    print('✓ No unclosed tag errors detected')

if validator.tags:
    print(f'⚠ Unclosed tags: {validator.tags}')
else:
    print('✓ All tags properly closed')

# Check for essential accessibility
if 'alt=' in content:
    alts = content.count('alt=')
    print(f'✓ {alts} images have alt attributes')
if 'aria-label' in content:
    print('✓ ARIA labels present')
"
